				{
					body->setCoordinateFrame(value);
					assembly->notifyMoved();
					world->onAssemblyExtentsChanged(assembly);
					if (!(dragging || anchored || jointAnchored))
						world->ticklePrimitive(this, 0);
				}
			}
		}
	}
